#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin. Created: 2026-09-07
# /ork:page-serve serve: hand a human a rendered HTML page at a stable HTTPS URL.
#
# What it does, in order:
#   1. Refuses loudly if portless is missing or its 443 service is not responding
#      (the URL contract is https://<name>.localhost/ with NO port; a port in the
#      URL means the pre-service fallback and is a bug, not a feature).
#   2. Starts one static server (python3 http.server) on a free loopback port,
#      rooted at the file's directory or the directory itself.
#   3. Registers `portless alias <name> <port>` so the page is reachable at
#      https://<name>.localhost/<file>.
#   4. Optionally takes a screenshot through agent-browser and prints its path.
#   5. Records everything under .claude/state/page-serve/<name>.json so stop.sh
#      can tear it down and status.sh can list it.
#
# Idempotent per name: a second serve with the same name and the same root
# reuses the live server; a different root replaces it.
#
# Exit codes: 0 served, 1 usage, 2 prerequisite missing (portless / service),
#             3 server failed to start, 4 route registered but the URL did not
#             answer 200 (server is up; the caller decides).
#
# Replaces the ad hoc `python3 -m http.server` + hand-typed alias pattern, which
# left servers alive across sessions with no record (#3899, #3900).
#
# Style: no `| grep -q` under pipefail (the #3974 class); every status that
# becomes state is captured with its exit code; the four deliberate silences
# (two liveness probes, two cleanup kills) carry their tags inline.

set -euo pipefail

usage() {
  cat >&2 <<'EOF'
usage: serve.sh <path-to-html-or-dir> [--name <slug>] [--screenshot] [--no-screenshot]

  <path>          an .html file (served from its directory) or a directory
  --name <slug>   subdomain to register; default: derived from the path
  --screenshot    take a screenshot via agent-browser after serving (default when
                  agent-browser is installed)
  --no-screenshot skip the screenshot
EOF
  exit 1
}

[[ $# -ge 1 ]] || usage

TARGET=""
NAME=""
SHOT="auto"
while [[ $# -gt 0 ]]; do
  case "$1" in
    --name) NAME="${2:-}"; shift 2 ;;
    --screenshot) SHOT="yes"; shift ;;
    --no-screenshot) SHOT="no"; shift ;;
    -h|--help) usage ;;
    -*) printf 'serve.sh: unknown flag %s\n' "$1" >&2; usage ;;
    *) TARGET="$1"; shift ;;
  esac
done
[[ -n "$TARGET" ]] || usage

PROJECT_DIR="${CLAUDE_PROJECT_DIR:-$(pwd)}"
STATE_DIR="${PROJECT_DIR}/.claude/state/page-serve"
mkdir -p "$STATE_DIR"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# ── 1. Resolve the target ────────────────────────────────────────────────────
if [[ -d "$TARGET" ]]; then
  ROOT="$(cd "$TARGET" && pwd)"
  FILE=""
elif [[ -f "$TARGET" ]]; then
  ROOT="$(cd "$(dirname "$TARGET")" && pwd)"
  FILE="$(basename "$TARGET")"
else
  printf 'serve.sh: %s is neither a file nor a directory\n' "$TARGET" >&2
  exit 1
fi

if [[ -z "$NAME" ]]; then
  base="${FILE:-$(basename "$ROOT")}"
  base="${base%.html}"
  NAME="$(printf '%s' "$base" | tr '[:upper:]' '[:lower:]' | sed -E 's/[^a-z0-9]+/-/g; s/^-+//; s/-+$//' | cut -c1-40)"
  [[ -n "$NAME" ]] || NAME="page"
fi
if ! [[ "$NAME" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]]; then
  printf 'serve.sh: name "%s" is not a valid subdomain label (a-z, 0-9, hyphens)\n' "$NAME" >&2
  exit 1
fi
STATE_FILE="${STATE_DIR}/${NAME}.json"

# ── 2. Prerequisites, fail loud ──────────────────────────────────────────────
if ! command -v portless >/dev/null 2>&1; then
  printf 'serve.sh: portless is not installed. Install: npm i -g portless   (then: portless service install)\n' >&2
  exit 2
fi
svc_out="$(portless service status 2>&1)"; svc_rc=$?
case "$svc_out" in
  *"Proxy on 443: responding"*) ;;
  *)
    printf 'serve.sh: the portless 443 service is not responding (portless service status rc=%s).\n' "$svc_rc" >&2
    printf '  A dead-but-installed service needs the operator: sudo launchctl kickstart -k system/sh.portless.proxy\n' >&2
    printf '  Do not fall back to a :port URL; that is the bug this skill exists to remove.\n' >&2
    exit 2 ;;
esac
if ! command -v python3 >/dev/null 2>&1; then
  printf 'serve.sh: python3 not found (used for the static server)\n' >&2
  exit 2
fi

# ── 3. Reuse or start the static server ──────────────────────────────────────
read_state() { python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); print(d.get(sys.argv[2], ""))' "$STATE_FILE" "$1"; }

live_pid=0
PORT=""
if [[ -f "$STATE_FILE" ]]; then
  prev_root="$(read_state root)"
  prev_pid="$(read_state pid)"
  prev_port="$(read_state port)"
  # silent: gating-relaxed (kill -0 is a liveness probe; a dead pid is the expected "no")
  if [[ -n "$prev_pid" && "$prev_pid" != "0" ]] && kill -0 "$prev_pid" 2>/dev/null; then
    if [[ "$prev_root" == "$ROOT" ]]; then
      live_pid="$prev_pid"; PORT="$prev_port"
    else
      # silent: post-cleanup (replacing a server that may already have exited)
      kill "$prev_pid" 2>/dev/null || true
      sleep 0.3
    fi
  fi
fi

if [[ "$live_pid" == "0" ]]; then
  PORT="$(python3 -c 'import socket; s=socket.socket(); s.bind(("127.0.0.1",0)); print(s.getsockname()[1]); s.close()')"
  LOG="${STATE_DIR}/${NAME}.log"
  ( cd "$ROOT" && exec python3 -m http.server "$PORT" --bind 127.0.0.1 >"$LOG" 2>&1 ) &
  live_pid=$!
  ok=0
  for _ in $(seq 1 30); do
    # silent: gating-relaxed (readiness poll; connection refused is the expected early answer)
    if python3 -c 'import socket,sys; s=socket.socket(); s.settimeout(0.2); s.connect(("127.0.0.1",int(sys.argv[1]))); s.close()' "$PORT" 2>/dev/null; then ok=1; break; fi
    sleep 0.1
  done
  if [[ "$ok" != "1" ]]; then
    printf 'serve.sh: static server did not come up on 127.0.0.1:%s (log: %s)\n' "$PORT" "$LOG" >&2
    # silent: post-cleanup (the process that failed to start)
    kill "$live_pid" 2>/dev/null || true
    exit 3
  fi
fi

# ── 4. Register the route (--force overrides a stale alias for the same name) ─
alias_out="$(portless alias "$NAME" "$PORT" --force 2>&1)"; alias_rc=$?
if [[ "$alias_rc" != "0" ]]; then
  printf 'serve.sh: portless alias %s %s failed (rc=%s): %s\n' "$NAME" "$PORT" "$alias_rc" "$alias_out" >&2
  # silent: post-cleanup (undo the server we just started)
  kill "$live_pid" 2>/dev/null || true
  exit 2
fi

URL="https://${NAME}.localhost/${FILE}"

# ── 5. Record state ──────────────────────────────────────────────────────────
python3 - "$STATE_FILE" "$NAME" "$ROOT" "$FILE" "$PORT" "$live_pid" "$URL" <<'PY'
import json, sys, datetime
f, name, root, file, port, pid, url = sys.argv[1:8]
json.dump({"name": name, "root": root, "file": file, "port": int(port), "pid": int(pid),
           "url": url, "started_at": datetime.datetime.now(datetime.timezone.utc).isoformat()},
          open(f, "w"), indent=2)
PY

# ── 6. Verify the URL answers through the proxy (portless CA is self-signed: -k) ─
code="$(curl -sSk -o /dev/null -m 8 -w '%{http_code}' "$URL" 2>&1)"; curl_rc=$?
if [[ "$curl_rc" != "0" || "$code" != "200" ]]; then
  printf 'serve.sh: %s answered %s (curl rc=%s), not 200. The server is up on :%s; check: portless list\n' "$URL" "$code" "$curl_rc" "$PORT" >&2
  final_rc=4
else
  final_rc=0
fi

# ── 7. Optional screenshot ───────────────────────────────────────────────────
SHOT_PATH=""
if [[ "$SHOT" == "auto" ]]; then
  if command -v agent-browser >/dev/null 2>&1; then SHOT="yes"; else SHOT="no"; fi
fi
if [[ "$SHOT" == "yes" ]]; then
  if command -v agent-browser >/dev/null 2>&1; then
    SHOT_PATH="${STATE_DIR}/${NAME}.png"
    shot_out="$(agent-browser open "$URL" 2>&1 && agent-browser screenshot "$SHOT_PATH" 2>&1)"; shot_rc=$?
    if [[ "$shot_rc" != "0" || ! -s "$SHOT_PATH" ]]; then
      printf 'serve.sh: screenshot failed (agent-browser rc=%s): %s. The page is still served.\n' "$shot_rc" "${shot_out:0:200}" >&2
      SHOT_PATH=""
    fi
  else
    printf 'serve.sh: --screenshot asked but agent-browser is not installed; skipping.\n' >&2
  fi
fi

printf 'url=%s\n' "$URL"
printf 'name=%s\nport=%s\npid=%s\nhttp=%s\n' "$NAME" "$PORT" "$live_pid" "$code"
[[ -n "$SHOT_PATH" ]] && printf 'screenshot=%s\n' "$SHOT_PATH"
printf 'stop=%s/stop.sh %s\n' "$SCRIPT_DIR" "$NAME"
exit "$final_rc"
